# v5.18: o gestor que relata nota dada com IA por um professor (teste da v5.17, T5).
_IA = r'(chat ?gpt|chat\w*|gpt|gemini|copilot|ia|inteligencia artificial)'
CONCEITOS['ge_correcao'] += (r'|\b(dar|deu|dando|da|dao|deram|lanc\w+|atribui\w+|fech\w+) (a |as )?notas? .{0,25}\b' + _IA + r'\b'
                             r'|\b(usa|usou|usam|usaram|usando|usar) (a |o )?' + _IA + r' (para|pra) (dar|lancar|atribuir|calcular|corrigir|fechar) (a |as )?(notas?|provas?|redac\w+|trabalhos?)\b'
                             r'|\bcorrig\w+ .{0,25}\b(com|usando|n[oa]|pel[oa]) (a |o )?' + _IA + r'\b'
                             r'|\bnotas? (gerad|dad|feit|atribuid|calculad|lancad)\w+ (pel[oa]|por|com|n[oa]) (a |o )?' + _IA + r'\b')
